mapper.select:
select
shrr.id,shrr.rent_start_time,shrr.rent_end_time,sh.name houseName,sh.build_area,sh.cover_area,sb.name
buildingName,sp.org_name parkOrgName
from


    shrr.company_id = #{companyId}
    and shrr.bind = 1
    and shrr.deleted = 0

        and sb.id = #{buildingId}


        and sh.id = #{houseId}


order by sh.name,sb.name,sp.org_name

select
shrr.id,shrr.rent_start_time,shrr.rent_end_time,shrr.unbind_time,shrr.bind,sh.name
houseName,sh.build_area,sh.cover_area,sb.name buildingName,sp.org_name parkOrgName,sc.name companyName
from



        sp.id = #{parkOrgId}


        and sp.id in

            #{parkOrgId}



        and sb.id = #{buildingId}


        and sh.id = #{houseId}


        and sc.name like "%"#{companyName}"%"

    and shrr.deleted = 0

order by shrr.create_time desc,sh.name,sb.name,sp.org_name
